lass="modal-dialog"><div class="modal-header"><h2 style="margin-top:0"><?= $id ? 'Editar':'Nuevo'?> usuario</h2><a class="modal-close" href="/controllers/usuarios.php" data-modal-close aria-label="Cerrar">×</a></div><div class="modal-body"><?php if ($formError ?? null): ?><div class="alert alert-error" role="alert"><?= e($formError) ?></div><?php endif; ?><form method="post" data-user-form data-next-docente="<?=e($siguienteDocente)?>" data-next-estudiante="<?=e($siguienteEstudiante)?>"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="accion" value="guardar"><input type="hidden" name="id" value="<?= (int)$id ?>"><div class="grid grid-2"><div class="form-group"><label class="form-label">Nombre</label><input required name="nombre" data-only-letters data-person-name value="<?=e($registro['nombre']??'')?>"></div><div class="form-group"><label class="form-label">Apellido</label><input required name="apellido" data-only-letters data-person-name value="<?=e($registro['apellido']??'')?>"></div><div class="form-group"><label class="form-label">Correo</label><input required type="email" name="correo" data-upds-email pattern="[A-Za-z0-9._%+-]+@upds\.net\.com" value="<?=e($registro['correo']??'')?>" placeholder="nombre@upds.net.com"></div><div class="form-group"><label class="form-label">Usuario</label><input required name="usuario" value="<?=e($registro['usuario']??'')?>" placeholder="Se actualiza según el rol seleccionado"><div class="form-help">Escribe el usuario manualmente. La sugerencia cambia según el rol y los usuarios ya registrados.</div></div><div class="form-group"><label class="form-label">Rol</label><select required name="id_rol"><option value="">Selecciona un rol</option><?php foreach($roles as $r):?><option value="<?=$r['id_rol']?>" <?=($registro['id_rol']??'')==$r['id_rol']?'selected':''?>><?=e($r['nombre_rol'] === 'docente' ? 'Docente' : ucfirst($r['nombre_rol']))?></option><?php endforeach;?></select></div><div class="form-group"><label class="form-label">Estado</label><select name="estado"><option value="activo" <?=($registro['estado']??'activo')==='activo'?'selected':''?>>Activo</option><option value="inactivo" <?=($registro['estado']??'')==='inactivo'?'selected':''?>>Inactivo</option></select></div><div class="form-group"><label class="form-label">Teléfono</label><input name="telefono" inputmode="numeric" maxlength="8" pattern="[0-9]{8}" data-phone-bolivia placeholder="8 dígitos" value="<?=e($registro['telefono']??'')?>"></div><div class="form-group"><label class="form-label">Contraseña <?= $id?'(opcional)':''?></label><input type="password" name="clave" <?= $id?'':'required'?>><div class="form-help"><?= $id ? 'En blanco = no se cambia la contraseña actual.' : 'Usa una contraseña segura.' ?></div></div><div class="form-group"><label class="form-label">Confirmar contraseña</label><input type="password" name="confirmar_clave" <?= $id?'':'required'?>></div></div><div class="actions"><button class="btn btn-primary">Guardar</button><a class="btn btn-light" href="/controllers/usuarios.php">Cancelar</a></div></form></div></div></div><?php endif;?><?php include __DIR__.'/../layouts/footer.php';?>
